#![deny(clippy::unwrap_used, clippy::expect_used)]
//! Phase 6: C-ABI Host Interface & Auto-Generated `.h` Header Emitter.
//! Generates C11/C++ compatible SoA descriptors (`AeroVec3Simd4`, `AeroQuat`, `AeroMat3`,
//! `<State>_SoA`) with `_Static_assert` alignment proofs and batched FFI signatures.

use aerotick_mir::{MirProgram, MirType};

/// 32-byte aligned 4-lane SIMD vector matching the C-ABI `AeroVec3Simd4` layout.
#[repr(C, align(32))]
#[derive(Debug, Clone, Copy, Default, PartialEq)]
pub struct AeroVec3Simd4 {
    pub x: f64,
    pub y: f64,
    pub z: f64,
    pub pad: f64,
}

/// 32-byte aligned 4-lane unit quaternion (`w, x, y, z`) matching C-ABI `AeroQuat`.
#[repr(C, align(32))]
#[derive(Debug, Clone, Copy, Default, PartialEq)]
pub struct AeroQuat {
    pub w: f64,
    pub x: f64,
    pub y: f64,
    pub z: f64,
}

/// 32-byte aligned 3x4 padded 3x3 matrix matching C-ABI `AeroMat3`.
#[repr(C, align(32))]
#[derive(Debug, Clone, Copy, Default, PartialEq)]
pub struct AeroMat3 {
    pub rows: [AeroVec3Simd4; 3],
}

/// Emits a self-contained C11/C++ header (`aerotick.h`) for the compiled `MirProgram`.
pub fn emit_c_header(mir: &MirProgram) -> String {
    let mut lines = vec![
        "/* Auto-generated by AeroTick Ultra v2.0 (aeroc) — C11/C++ ABI Host Interface */"
            .to_string(),
        "#pragma once".to_string(),
        "#include <stddef.h>".to_string(),
        "#include <stdint.h>".to_string(),
        "#if !defined(__cplusplus)".to_string(),
        "#include <stdalign.h>".to_string(),
        "#endif".to_string(),
        String::new(),
        "#if defined(__cplusplus)".to_string(),
        "  #define AEROTICK_ALIGN32 alignas(32)".to_string(),
        "  #define AEROTICK_ALIGNOF(T) alignof(T)".to_string(),
        "  #define AEROTICK_STATIC_ASSERT(cond, msg) static_assert(cond, msg)".to_string(),
        "  #define AEROTICK_RESTRICT __restrict".to_string(),
        "extern \"C\" {".to_string(),
        "#else".to_string(),
        "  #define AEROTICK_ALIGN32 _Alignas(32)".to_string(),
        "  #define AEROTICK_ALIGNOF(T) _Alignof(T)".to_string(),
        "  #define AEROTICK_STATIC_ASSERT(cond, msg) _Static_assert(cond, msg)".to_string(),
        "  #define AEROTICK_RESTRICT restrict".to_string(),
        "#endif".to_string(),
        String::new(),
        "/* 32-byte aligned 4-lane SIMD vector (x, y, z, _pad) */".to_string(),
        "typedef struct {".to_string(),
        "    AEROTICK_ALIGN32 double x;".to_string(),
        "    double y;".to_string(),
        "    double z;".to_string(),
        "    double _pad;".to_string(),
        "} AeroVec3Simd4;".to_string(),
        "AEROTICK_STATIC_ASSERT(sizeof(AeroVec3Simd4) == 32, \"AeroVec3Simd4 must be 32 bytes\");"
            .to_string(),
        "AEROTICK_STATIC_ASSERT(AEROTICK_ALIGNOF(AeroVec3Simd4) == 32, \"AeroVec3Simd4 must be 32B aligned\");"
            .to_string(),
        String::new(),
        "/* 32-byte aligned 4-lane unit quaternion (w, x, y, z) */".to_string(),
        "typedef struct {".to_string(),
        "    AEROTICK_ALIGN32 double w;".to_string(),
        "    double x;".to_string(),
        "    double y;".to_string(),
        "    double z;".to_string(),
        "} AeroQuat;".to_string(),
        "AEROTICK_STATIC_ASSERT(sizeof(AeroQuat) == 32, \"AeroQuat must be 32 bytes\");"
            .to_string(),
        "AEROTICK_STATIC_ASSERT(AEROTICK_ALIGNOF(AeroQuat) == 32, \"AeroQuat must be 32B aligned\");"
            .to_string(),
        String::new(),
        "/* 32-byte aligned 3x3 inertial/frame matrix (3 padded SIMD4 rows = 96B) */".to_string(),
        "typedef struct {".to_string(),
        "    AeroVec3Simd4 rows[3];".to_string(),
        "} AeroMat3;".to_string(),
        "AEROTICK_STATIC_ASSERT(sizeof(AeroMat3) == 96, \"AeroMat3 must be 96 bytes\");"
            .to_string(),
        "AEROTICK_STATIC_ASSERT(AEROTICK_ALIGNOF(AeroMat3) == 32, \"AeroMat3 must be 32B aligned\");"
            .to_string(),
        String::new(),
    ];

    for layout in &mir.layouts {
        lines.push(format!(
            "/* SoA descriptor for state '{}' ({} bytes/entity, {}x64B cache lines) */",
            layout.state_name,
            layout.total_bytes_per_entity,
            layout.cache_lines_64b()
        ));
        lines.push("typedef struct {".to_string());
        for f in &layout.fields {
            match f.mir_type {
                MirType::Vec3Simd4 => {
                    lines.push(format!("    AeroVec3Simd4* {}; /* 32B aligned */", f.name));
                }
                MirType::QuatSimd4 => {
                    lines.push(format!("    AeroQuat* {}; /* 32B aligned */", f.name));
                }
                MirType::Mat3Simd12 => {
                    lines.push(format!("    AeroMat3* {}; /* 32B aligned */", f.name));
                }
                _ => {
                    lines.push(format!("    double* {}; /* 8B aligned */", f.name));
                }
            }
        }
        lines.push(format!("}} {}_SoA;", layout.state_name));
        lines.push(String::new());
    }

    for sys in &mir.systems {
        let lower = sys.name.to_lowercase();
        lines.push(format!(
            "void aerotick_step_{lower}(const {}_SoA* AEROTICK_RESTRICT prev, {}_SoA* AEROTICK_RESTRICT next, size_t count, double {});",
            sys.state_name, sys.state_name, sys.dt_param
        ));
        lines.push(format!(
            "void aerotick_step_batch_{lower}(const {}_SoA* AEROTICK_RESTRICT prev, {}_SoA* AEROTICK_RESTRICT next, size_t count, double {});",
            sys.state_name, sys.state_name, sys.dt_param
        ));
    }

    lines.push(String::new());
    lines.push("#if defined(__cplusplus)".to_string());
    lines.push("}".to_string());
    lines.push("#endif".to_string());
    lines.join("\n")
}

#[cfg(test)]
mod tests {
    use super::*;
    use aerotick_lexer::lex;
    use aerotick_mir::lower_to_mir;
    use aerotick_parser::parse;
    use aerotick_sema::analyze;

    #[test]
    fn generates_c_header_with_static_asserts_and_batched_ffi() {
        let src = include_str!("../../../examples/rocket_6dof.aero");
        let (tokens, _) = lex(src);
        let (ast_opt, p_errs) = parse(&tokens, src.len());
        assert!(p_errs.is_empty(), "{p_errs:?}");
        let Some(ast) = ast_opt else {
            panic!("expected AST");
        };
        let (hir, s_errs) = analyze(&ast);
        assert!(s_errs.is_empty(), "{s_errs:?}");
        let mir = lower_to_mir(&hir);
        let header = emit_c_header(&mir);
        assert!(header.contains("AeroVec3Simd4"));
        assert!(header.contains("AeroQuat"));
        assert!(header.contains("AeroMat3"));
        assert!(header.contains("AEROTICK_STATIC_ASSERT(sizeof(AeroVec3Simd4) == 32"));
        assert!(header.contains("AEROTICK_STATIC_ASSERT(sizeof(AeroQuat) == 32"));
        assert!(header.contains("AEROTICK_STATIC_ASSERT(sizeof(AeroMat3) == 96"));
        assert!(header.contains("Rocket6DoF_SoA"));
        assert!(header.contains("aerotick_step_rocket6dofstep("));
        assert!(header.contains("aerotick_step_batch_rocket6dofstep("));
    }
}
